import os,subprocess
root='/mnt/local-analysis/workspace-hub'
# gather candidate dirs containing .git (dir or file)
for dirpath, dirnames, filenames in os.walk(root):
    if '.git' in dirnames or '.git' in filenames:
        try:
            r=subprocess.run(['git','-C',dirpath,'cat-file','-t','22e66dd'],capture_output=True,text=True)
            if r.returncode==0:
                print(dirpath)
        except Exception:
            pass
        # don't recurse into nested repos deeply maybe huge; but keep
